import emitter from '@ohos.events.emitter';

export class EmitterConst {
  static readonly ADD_EVENT_ID: number = 2;
}

class EventsId {
  eventId: number;
  constructor(eventId: number) {
    this.eventId = eventId;
  }
}

export class Bus {
  subscribeCart(callback: Function): void {
    let addGoodDataId: EventsId = new EventsId(EmitterConst.ADD_EVENT_ID);
    emitter.on(addGoodDataId, (eventData) => {
      callback(eventData);
    });
  }

  publishAdd(goodId: number): void {
    let addToCartId: EventsId = new EventsId(EmitterConst.ADD_EVENT_ID);
    emitter.emit(addToCartId);
  }
}

